    ax.set_ylim(global_min * 0.95, global_max * 1.05)
    ax.tick_params(labelsize=10)

# Only show x-labels on bottom row, y-labels on left column
for ax in axes[0, :]:
    ax.tick_params(labelbottom=False)
for ax in axes[:, 1]:
    ax.tick_params(labelleft=False)

plt.tight_layout()
plt.show()
